dsh-persona:
z.object({
	prefix: z.string().required(),
	suffix: z.string().default(""),
	complete: z.boolean().default(false),
	includeRuntimeContext: z.boolean().default(true)
})

dsh-tool-fs:
z.object({
	readLimit: z.number().default(READ_LIMIT),
	readMaxLineLength: z.number().default(READ_MAX_LINE_LENGTH),
	readMaxBytes: z.number().default(READ_MAX_BYTES),
	readStreamMinSize: z.number().default(STREAM_MIN_SIZE)
})

dsh-tool-jobs:
z.object({
	waitTimeoutMs: z.number().min(1).default(3e4),
	maxWaitTimeoutMs: z.number().min(1).default(6e5),
	completionDelivery: z.union(["quiet", "wakeup"]).default("wakeup"),
	maxConsecutiveWakes: z.number().min(1)
})

dsh-tool-subagent:
z.object({
	provider: z.string().required(),
	toolName: z.string().default("subagent"),
	modelSelectionSettings: z.boolean().default(false),
	enableRunInBackground: z.boolean().default(true),
	backgroundMode: z.union(["one-shot", "continuable"]).default("one-shot"),
	agentOptions: z.object({
		provider: z.string(),
		model: z.string(),
		reasoningEffort: z.string().min(1),
		maxTokens: z.number().step(1).min(1).max(Number.MAX_SAFE_INTEGER)
	}).default(void 0),
	persona: z.string(),
	toolFilter: z.object({
		allow: z.array(z.string()).default(void 0),
		deny: z.array(z.string()).default(void 0)
	}).default(void 0),
	maxDepth: z.union([z.natural().max(Number.MAX_SAFE_INTEGER), z.const("provider-managed")])
})

dsh-tool-workflow:
z.object({
	toolName: z.string().default("workflow"),
	maxResultChars: z.natural().min(1).default(5e4),
	enableRunInBackground: z.boolean().default(true)
})

dsh-tool-ralph:
z.object({
	subagentProvider: z.string().default("spawn"),
	maxRounds: z.number().step(1).min(1).max(Number.MAX_SAFE_INTEGER).default(256),
	maxHandoffChars: z.number().step(1).min(1).max(Number.MAX_SAFE_INTEGER).default(16384),
	maxResultChars: z.number().step(1).min(1).max(Number.MAX_SAFE_INTEGER).default(16384)
})
